// 1. Selecionando elementos do DOM
const btnCurtir = document.querySelector('#btn-curtir');
const contadorText = document.querySelector('#curtidas-count');

let totalCurtidas = 0;

// 2. Registrando um ouvinte de eventos (Event Listener)
btnCurtir.addEventListener('click', () => {
  totalCurtidas += 1;
  contadorText.textContent = `${totalCurtidas} curtidas`;

  // Alterna uma classe CSS
  btnCurtir.classList.toggle('active');
});

const listaAulas = document.querySelector('#lista-aulas');

function adicionarNovaAula(titulo, tag) {
  // Cria o elemento <li>
  const li = document.createElement('li');
  li.className = 'list-group-item d-flex justify-content-between align-items-center';

  // Preenche o conteúdo
  li.innerHTML = `
    <span>${titulo}</span>
    <span class="badge bg-success">${tag}</span>
  `;

  // Anexa à lista no DOM
  listaAulas.appendChild(li);
}
